// CreateRestore creates a new restore operation
func (r *mutationResolver) CreateRestore(ctx context.Context, input CreateRestoreInput) (*RestorePayload, error) {
	// Get authenticated user
	user, err := getAuthenticatedUser(ctx)
	if err != nil {
		return nil, err
	}

	// Create restore configuration
	restoreID := uuid.New().String()
	targetDB := ""
	if input.TargetDatabase != nil {
		targetDB = *input.TargetDatabase
	}

	config := &types.RestoreConfig{
		BackupID:         input.BackupID,
		TargetDatabaseID: targetDB,
		Tables:           input.Tables,
		ExcludeTables:    input.ExcludeTables,
	}

	if input.PointInTime != nil {
		pitr := input.PointInTime.ToTime()
		config.PointInTime = &pitr
	}

	// Create restore record (actual restore would be async)
	// In production, this would call a restore service to start the operation
	// For now, we create a tracking record
	result := struct {
		ID       string
		Database string
	}{
		ID:       restoreID,
		Database: targetDB,
	}

	// Convert to GraphQL type
	graphQLRestore := &Restore{
		ID:             result.ID,
		BackupID:       input.BackupID,
		Status:         RestoreStatusInProgress,
		Progress:       0,
		StartedAt:      scalar.TimeToDateTime(time.Now()),
		StartedBy:      user.ID,
		TargetDatabase: result.Database,
	}

	// Publish to subscription
	r.publishRestoreProgress(graphQLRestore, 0)

	return &RestorePayload{
		Success: true,
		Message: "Restore started successfully",
		Restore: graphQLRestore,
	}, nil
}

